CREATE TABLE metadata_edit_drafts(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,state TEXT NOT NULL,payload_json TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE metadata_edit_previews(id TEXT PRIMARY KEY,draft_id TEXT NOT NULL REFERENCES metadata_edit_drafts(id),draft_revision INTEGER NOT NULL,state TEXT NOT NULL,payload_json TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE metadata_edit_batches(id TEXT PRIMARY KEY,draft_id TEXT NOT NULL REFERENCES metadata_edit_drafts(id),draft_revision INTEGER NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,payload_json TEXT NOT NULL,undo_of TEXT REFERENCES metadata_edit_batches(id),created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE metadata_edit_rows(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES metadata_edit_batches(id),track_id TEXT NOT NULL REFERENCES tracks(id),ordinal INTEGER NOT NULL,state TEXT NOT NULL,payload_json TEXT NOT NULL,error TEXT,result_json TEXT,UNIQUE(batch_id,ordinal));
CREATE TABLE metadata_edit_writes(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES metadata_edit_batches(id),row_id TEXT NOT NULL REFERENCES metadata_edit_rows(id),track_id TEXT NOT NULL REFERENCES tracks(id),state TEXT NOT NULL,payload_json TEXT NOT NULL,workspace BLOB NOT NULL,error TEXT,undo_of TEXT REFERENCES metadata_edit_writes(id),override_of TEXT REFERENCES jobs(id),expected_path_revision INTEGER NOT NULL,expected_metadata_revision INTEGER NOT NULL,output_hash TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE metadata_edit_files(write_id TEXT NOT NULL REFERENCES metadata_edit_writes(id),ordinal INTEGER NOT NULL,target BLOB NOT NULL,staged BLOB NOT NULL,backup BLOB,before_hash TEXT,after_hash TEXT NOT NULL,publish_path BLOB NOT NULL,displaced_path BLOB NOT NULL,PRIMARY KEY(write_id,ordinal));
CREATE TABLE metadata_artwork_assets(id TEXT PRIMARY KEY,sha256 TEXT NOT NULL,mime TEXT NOT NULL,path BLOB NOT NULL,bytes INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE metadata_edit_overrides(job_id TEXT PRIMARY KEY REFERENCES jobs(id),track_id TEXT NOT NULL REFERENCES tracks(id),draft_id TEXT NOT NULL REFERENCES metadata_edit_drafts(id),draft_revision INTEGER NOT NULL,batch_id TEXT NOT NULL REFERENCES metadata_edit_batches(id),source_hash TEXT NOT NULL,settings_revision TEXT NOT NULL,path_revision INTEGER NOT NULL,metadata_revision INTEGER NOT NULL,accepted_attempt INTEGER NOT NULL,claimed_attempt INTEGER,execution_source_proof_json TEXT NOT NULL,receipt_json TEXT,final_json TEXT,undo_batch_id TEXT REFERENCES metadata_edit_batches(id),state TEXT NOT NULL,payload_json TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE INDEX metadata_edit_pending ON metadata_edit_writes(state,track_id);
CREATE INDEX metadata_edit_write_batches ON metadata_edit_writes(batch_id,state);
CREATE INDEX metadata_edit_write_rows ON metadata_edit_writes(row_id,created);
CREATE INDEX metadata_edit_file_targets ON metadata_edit_files(target);
CREATE INDEX metadata_edit_row_outcomes ON metadata_edit_rows(batch_id,state);
CREATE INDEX metadata_edit_override_batches ON metadata_edit_overrides(batch_id,state);
PRAGMA user_version=19;
